const send=(res,status,data,headers={})=>{
  const isBuf=typeof data==='string'||Buffer.isBuffer(data);
  const body=isBuf?data:JSON.stringify(data);
  res.writeHead(status,{...secureHeaders(),'Content-Type':isBuf?'text/plain; charset=utf-8':'application/json; charset=utf-8','Cache-Control':'no-store',...headers});
  res.end(body);
};
