function dashboardPayStats(day){
  const today={},total={},outToday={},outTotal={};
  for(const m of PAY_METHODS){const inc=(where,args)=>Number(db.prepare('SELECT COALESCE(SUM(amount_cents),0) c FROM payments WHERE pay_method=? AND bill_kind<>\'退货\' '+where).get(m,...args)?.c||0);today[m]=inc('AND substr(created_at,1,10)=?',[day]);total[m]=inc('',[]);const outc=(where,args)=>Number(db.prepare('SELECT COALESCE(SUM(amount_cents),0) c FROM supplier_payments WHERE pay_method=? '+where).get(m,...args)?.c||0);outToday[m]=outc('AND substr(occurred_at,1,10)=?',[day]);outTotal[m]=outc('',[])}
  const sum=o=>Object.entries(o).filter(([k])=>k!=='记账').reduce((n,[,v])=>n+Number(v||0),0);
  const todayIn=sum(today),totalIn=sum(total),todayOut=sum(outToday),totalOut=sum(outTotal);
  const creditToday=Number(db.prepare("SELECT COALESCE(SUM(total_cents),0) c FROM orders WHERE pay_method='记账' AND substr(created_at,1,10)=?").get(day)?.c||0);
  const creditTotal=Number(db.prepare("SELECT COALESCE(SUM(total_cents),0) c FROM orders WHERE pay_method='记账'").get()?.c||0);
  const grossToday=Number(db.prepare('SELECT COALESCE(SUM(gross_profit_cents),0) c FROM orders WHERE substr(created_at,1,10)=?').get(day)?.c||0);
  const grossTotal=Number(db.prepare('SELECT COALESCE(SUM(gross_profit_cents),0) c FROM orders').get()?.c||0);
  const returnTotal=Number(db.prepare("SELECT COALESCE(SUM(total_cents),0) c FROM returns WHERE status='已通过'").get()?.c||0);
  const loss=Number(db.prepare("SELECT COALESCE(SUM(amount_cents),0) c FROM stock_adjustments WHERE kind='报损'").get()?.c||0);
  const gain=Number(db.prepare("SELECT COALESCE(SUM(amount_cents),0) c FROM stock_adjustments WHERE kind='报溢'").get()?.c||0);
  const categoryCount=Number(db.prepare('SELECT COUNT(*) c FROM product_categories WHERE active=1').get()?.c||0);
  const brandCount=Number(db.prepare('SELECT COUNT(*) c FROM product_brands WHERE active=1').get()?.c||0);
  return {today,total,outToday,outTotal,today_in_cents:todayIn,total_in_cents:totalIn,today_out_cents:todayOut,total_out_cents:totalOut,today_net_cents:todayIn-todayOut,total_net_cents:totalIn-totalOut,credit_today_cents:creditToday,credit_total_cents:creditTotal,gross_today_cents:grossToday,gross_total_cents:grossTotal,return_total_cents:returnTotal,loss_cents:loss,gain_cents:gain,category_count:categoryCount,brand_count:brandCount};
}
